def _best_target_insertion(source, target, bg):
    """Align source with target, allowing one extra target cell."""
    w = len(source)
    target_last = max((j for j, v in enumerate(target) if v != bg), default=-1)
    candidates = []
    # No insertion.
    pairs = [(i, i) for i in range(w)]
    mismatches = sum(source[i] != target[j] for i, j in pairs if j <= target_last)
    candidates.append((mismatches, 0, w, pairs))
    # Target has one extra cell at k; prefer the latest equally good insertion.
    for k in range(target_last + 1):
        pairs = [(i, i if i < k else i + 1)
                 for i in range(w) if i < k or i + 1 < w]
        mismatches = sum(source[i] != target[j] for i, j in pairs if j <= target_last)
        candidates.append((mismatches, 1, k, pairs))
    _, has_gap, k, pairs = min(candidates, key=lambda x: (x[0], -x[1], -x[2]))
    return pairs, (k if has_gap else w)


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    if not active:
        return out
    bands = []
    start = prev = active[0]
    for r in active[1:]:
        if r != prev + 1:
            bands.append((start, prev + 1))
            start = r
        prev = r
    bands.append((start, prev + 1))
    if len(bands) < 2:
        return out
    (top0, top1), (bottom0, bottom1) = bands[0], bands[-1]
    if top1 - top0 != bottom1 - bottom0:
        return out

    for k in range(top1 - top0):
        r_top, r_bottom = top0 + k, bottom0 + k
        top, bottom = grid[r_top], grid[r_bottom]
        last_top = max((c for c, v in enumerate(top) if v != bg), default=-1)
        last_bottom = max((c for c, v in enumerate(bottom) if v != bg), default=-1)
        if last_top == last_bottom:
            continue
        if last_top > last_bottom:
            source, target, target_row = top, bottom, r_bottom
        else:
            source, target, target_row = bottom, top, r_top
        pairs, gap = _best_target_insertion(source, target, bg)
        source_for_target = {j: i for i, j in pairs}
        target_last = max((c for c, v in enumerate(target) if v != bg), default=-1)
        for j in range(target_last + 1, w):
            if j == gap:
                continue
            i = source_for_target.get(j)
            if i is not None and target[j] == bg and source[i] != bg:
                out[target_row][j] = 1
    return out
